const resolveLink = `-- name: ResolveLink :one
SELECT l.id, l.owner_id, l.node_id, l.token, l.source, l.created_ip, l.created_ua, l.api_key_id, l.referer_hosts, l.allow_no_referer, l.daily_bytes_cap, l.auto_pause, l.has_gps, l.expires_at, l.paused_at, l.pause_reason, l.revoked_at, l.hits_total, l.bytes_total, l.last_hit_at, l.created_at, n.name AS node_name, n.deleted_at AS node_deleted_at, n.updated_at AS node_updated_at,
    b.sha256 AS blob_sha256, b.size AS blob_size, b.mime AS blob_mime,
    u.disabled_at AS owner_disabled_at,
    p.referer_hosts AS pref_referer_hosts, p.allow_no_referer AS pref_allow_no_referer
FROM links l
JOIN nodes n ON n.id = l.node_id
LEFT JOIN blobs b ON b.id = n.blob_id
JOIN users u ON u.id = l.owner_id
LEFT JOIN link_prefs p ON p.owner_id = l.owner_id
WHERE l.token = $1 AND l.revoked_at IS NULL
`

type ResolveLinkRow struct {
	Link               Link
	NodeName           string
	NodeDeletedAt      pgtype.Timestamptz
	NodeUpdatedAt      pgtype.Timestamptz
	BlobSha256         *string
	BlobSize           *int64
	BlobMime           *string
	OwnerDisabledAt    pgtype.Timestamptz
	PrefRefererHosts   []string
	PrefAllowNoReferer *bool
}

// /x/{token}:一次查出直链、文件、内容与属主状态。
func (q *Queries) ResolveLink(ctx context.Context, token string) (ResolveLinkRow, error) {
	row := q.db.QueryRow(ctx, resolveLink, token)
	var i ResolveLinkRow
	err := row.Scan(
		&i.Link.ID,
		&i.Link.OwnerID,
		&i.Link.NodeID,
		&i.Link.Token,
		&i.Link.Source,
		&i.Link.CreatedIp,
		&i.Link.CreatedUa,
		&i.Link.ApiKeyID,
		&i.Link.RefererHosts,
		&i.Link.AllowNoReferer,
		&i.Link.DailyBytesCap,
		&i.Link.AutoPause,
		&i.Link.HasGps,
		&i.Link.ExpiresAt,
		&i.Link.PausedAt,
		&i.Link.PauseReason,
		&i.Link.RevokedAt,
		&i.Link.HitsTotal,
		&i.Link.BytesTotal,
		&i.Link.LastHitAt,
		&i.Link.CreatedAt,
		&i.NodeName,
		&i.NodeDeletedAt,
		&i.NodeUpdatedAt,
		&i.BlobSha256,
		&i.BlobSize,
		&i.BlobMime,
		&i.OwnerDisabledAt,
		&i.PrefRefererHosts,
		&i.PrefAllowNoReferer,
	)
	return i, err
}

