const upsertLinkPrefs = `-- name: UpsertLinkPrefs :one
INSERT INTO link_prefs (owner_id, referer_hosts, allow_no_referer, image_folder, strip_gps, updated_at)
VALUES ($1, $2, $3, $4, $5, now())
ON CONFLICT (owner_id) DO UPDATE SET referer_hosts = EXCLUDED.referer_hosts, allow_no_referer = EXCLUDED.allow_no_referer,
    image_folder = EXCLUDED.image_folder, strip_gps = EXCLUDED.strip_gps, updated_at = now()
RETURNING owner_id, referer_hosts, allow_no_referer, image_folder, strip_gps, updated_at
`

type UpsertLinkPrefsParams struct {
	OwnerID        uuid.UUID
	RefererHosts   []string
	AllowNoReferer bool
	ImageFolder    string
	StripGps       bool
}

func (q *Queries) UpsertLinkPrefs(ctx context.Context, arg UpsertLinkPrefsParams) (LinkPref, error) {
	row := q.db.QueryRow(ctx, upsertLinkPrefs,
		arg.OwnerID,
		arg.RefererHosts,
		arg.AllowNoReferer,
		arg.ImageFolder,
		arg.StripGps,
	)
	var i LinkPref
	err := row.Scan(
		&i.OwnerID,
		&i.RefererHosts,
		&i.AllowNoReferer,
		&i.ImageFolder,
		&i.StripGps,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertLinkReferer = `-- name: UpsertLinkReferer :exec
INSERT INTO link_referers (link_id, day, host, hits, bytes) VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (link_id, day, host) DO UPDATE SET hits = link_referers.hits + EXCLUDED.hits, bytes = link_referers.bytes + EXCLUDED.bytes
`

type UpsertLinkRefererParams struct {
	LinkID uuid.UUID
	Day    pgtype.Date
	Host   string
	Hits   int64
	Bytes  int64
}

func (q *Queries) UpsertLinkReferer(ctx context.Context, arg UpsertLinkRefererParams) error {
	_, err := q.db.Exec(ctx, upsertLinkReferer,
		arg.LinkID,
		arg.Day,
		arg.Host,
		arg.Hits,
		arg.Bytes,
	)
	return err
}

const upsertLinkStat = `-- name: UpsertLinkStat :exec

INSERT INTO link_stats (link_id, hour, hits, bytes, blocked, ips) VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (link_id, hour) DO UPDATE SET hits = link_stats.hits + EXCLUDED.hits, bytes = link_stats.bytes + EXCLUDED.bytes,
    blocked = link_stats.blocked + EXCLUDED.blocked, ips = GREATEST(link_stats.ips, EXCLUDED.ips)
`

type UpsertLinkStatParams struct {
	LinkID  uuid.UUID
	Hour    pgtype.Timestamptz
	Hits    int64
	Bytes   int64
	Blocked int64
	Ips     int32
}

// ---------- 计数落库(每 30 秒一批) ----------
func (q *Queries) UpsertLinkStat(ctx context.Context, arg UpsertLinkStatParams) error {
	_, err := q.db.Exec(ctx, upsertLinkStat,
		arg.LinkID,
		arg.Hour,
		arg.Hits,
		arg.Bytes,
		arg.Blocked,
		arg.Ips,
	)
	return err
}
